'use strict';
(()=>{
const {PETS,drawPet}=ForestPets,{ForestGame,WIDTH,HEIGHT,DANGER_Y}=ForestCore;
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
let saved={best:0,unlocked:[0,1,2],sound:false};try{Object.assign(saved,JSON.parse(localStorage.getItem('momo-forest-v1')||'{}'));}catch{}
let game,drawX=230,particles=[],floaters=[],shakeUntil=0,toastTimer,last=0,accumulator=0,dropAt=-10,audioContext=null,resumeAfterDialog=false,heldPointer=null;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
function save(){try{localStorage.setItem('momo-forest-v1',JSON.stringify(saved));}catch{}}
function sound(kind){if(!saved.sound)return;audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const melody=kind==='merge'?[523.25,659.25,783.99]:kind==='drop'?[330,260]:[440,554];melody.forEach((note,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),t=audioContext.currentTime+i*.065;osc.type='sine';osc.frequency.setValueAtTime(note,t);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.055,t+.012);gain.gain.exponentialRampToValueAtTime(.001,t+.22);osc.connect(gain);gain.connect(audioContext.destination);osc.start(t);osc.stop(t+.25);});}
function toast(message){clearTimeout(toastTimer);$('gameToast').textContent=message;$('gameToast').classList.add('show');toastTimer=setTimeout(()=>$('gameToast').classList.remove('show'),2300);}
function fitCanvas(el,w,h){const dpr=Math.min(devicePixelRatio||1,2);el.width=w*dpr;el.height=h*dpr;const c=el.getContext('2d');c.scale(dpr,dpr);return c;}
function petIcon(el,level,w=100,h=100,locked=false,r){const c=fitCanvas(el,w,h);drawPet(c,level,w/2,h*.57,r||Math.min(w,h)*.32,0,0,{shadow:!locked,locked,still:true});}
function refreshCollection(){
 const unlocked=new Set(saved.unlocked);$('petGrid').replaceChildren();$('albumGrid').replaceChildren();PETS.forEach((pet,i)=>{const known=unlocked.has(i),cell=document.createElement('button');cell.className='pet-cell'+(known?'':' locked');cell.setAttribute('aria-label',known?`${pet.name}，等级 ${i+1}`:`等级 ${i+1}，尚未解锁`);const art=document.createElement('canvas'),name=document.createElement('span'),lv=document.createElement('span');name.textContent=known?pet.name:'未相遇';lv.className='level-label';lv.textContent=String(i+1).padStart(2,'0');cell.append(art,name,lv);$('petGrid').append(cell);petIcon(art,i,64,64,!known,22);cell.onclick=()=>openCollection(i);
 const album=document.createElement('button');album.className='album-cell'+(known?'':' locked');album.setAttribute('aria-label',known?pet.name:`等级 ${i+1}，尚未解锁`);const ac=document.createElement('canvas'),al=document.createElement('span'),title=document.createElement('h3'),desc=document.createElement('p');al.textContent=`LV. ${String(i+1).padStart(2,'0')}`;title.textContent=known?pet.name:'等待相遇';desc.textContent=known?pet.desc:`合成 ${i+1} 级宠物解锁`;album.append(ac,al,title,desc);$('albumGrid').append(album);petIcon(ac,i,100,95,!known,29);album.onclick=()=>selectAlbum(i);
 });$('unlockedCount').textContent=unlocked.size;$('navCount').textContent=`${unlocked.size} / 9`;$('collectionBar').style.width=`${unlocked.size/9*100}%`;
}
function selectAlbum(i){[...$('albumGrid').children].forEach((el,j)=>el.classList.toggle('active',i===j));$('albumMessage').textContent=saved.unlocked.includes(i)?PETS[i].story:`还没有遇见${PETS[i].name}。试着把两只${PETS[Math.max(0,i-1)].name}放在一起吧。`;}
function updateNext(){petIcon($('nextPet'),game.next,110,100,false,30);$('nextLevel').textContent=`LV. ${String(game.next+1).padStart(2,'0')}`;$('nextName').textContent=PETS[game.next].name;$('nextDesc').textContent=PETS[game.next].desc;}
function updateTools(){for(const name of['swap','remove','shake']){$(name+'Count').textContent=game.tools[name];$(name+'Btn').disabled=!game.tools[name]||game.state!=='playing';}$('removeBtn').classList.toggle('selected',game.removing);$('arenaHint').innerHTML=game.removing?'<span class="hint-dot"></span> 点击一只宠物，送它回森林':'<span class="hint-dot"></span> 移动瞄准，点击放下';canvas.parentElement.classList.toggle('removing',game.removing);}
function burst(x,y,color){if(reducedMotion)return;for(let i=0;i<18;i++){const a=i/18*Math.PI*2,s=1.1+(i%5)*.7;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-1,life:1,color,r:2+i%3});}}
function onGameEvent(e){if(e.type==='merge'){$('score').textContent=game.score;$('score').classList.remove('score-pop');void $('score').offsetWidth;$('score').classList.add('score-pop');if(game.score>saved.best){saved.best=game.score;$('bestScore').textContent=saved.best;}burst(e.x,e.y,PETS[e.level].color);floaters.push({x:e.x,y:e.y-35,text:`+${e.points}`,life:1.3});if(!saved.unlocked.includes(e.level)){saved.unlocked.push(e.level);refreshCollection();toast(`新朋友 · ${PETS[e.level].name}来啦！`);}else if(e.combo>1)toast(`太棒啦！连续合成 ×${e.combo}`);save();sound('merge');}else if(e.type==='drop'){dropAt=game.time;updateNext();sound('drop');}else if(e.type==='swap'){updateNext();toast('换个小伙伴，换个小惊喜');sound('tool');}else if(e.type==='shake'){shakeUntil=game.time+.45;toast('摇一摇，新的相遇正在发生');sound('tool');}else if(e.type==='removed'){burst(e.x,e.y,PETS[e.level].color);toast(`${PETS[e.level].name}回森林休息啦`);sound('tool');}else if(e.type==='remove-mode'){if(e.active)toast('点击场内一只宠物 · 再点道具取消');}else if(e.type==='end'){showEnd(e.won);}updateTools();}
function newGame(){if(game)game.destroy();game=new ForestGame({onEvent:onGameEvent});particles=[];floaters=[];drawX=230;dropAt=-10;shakeUntil=0;accumulator=0;$('score').textContent='0';$('bestScore').textContent=saved.best;$('pauseOverlay').hidden=true;$('endOverlay').hidden=true;$('pauseBtn').disabled=false;canvas.parentElement.classList.remove('in-danger');updateNext();updateTools();}
function showEnd(won){$('endOverlay').hidden=false;$('pauseBtn').disabled=true;$('endTitle').textContent=won?'森灵王，来见你啦！':'森林装满可爱了';$('endKicker').textContent=won?'整座森林都在为你欢呼':'一次小小的丰收';$('endScore').textContent=game.score;petIcon($('endPet'),game.bestLevel,140,140,false,46);if(won){burst(230,170,'#d5bc78');sound('merge');}}
function pause(){if(game.state==='playing'){game.pause();$('pauseOverlay').hidden=false;updateTools();}}
function resume(){game.resume();$('pauseOverlay').hidden=true;accumulator=0;last=performance.now();updateTools();}
function openDialog(id){if(document.querySelector('dialog[open]'))return;resumeAfterDialog=game.state==='playing';if(resumeAfterDialog)game.pause();$(id).showModal();updateTools();}
function openCollection(index=game.bestLevel){selectAlbum(index);openDialog('collectionDialog');}
for(const d of document.querySelectorAll('dialog')){d.querySelectorAll('.dialog-close,.dialog-close-action').forEach(b=>b.onclick=()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{if(resumeAfterDialog)game.resume();resumeAfterDialog=false;last=performance.now();accumulator=0;updateTools();});}
$('helpBtn').onclick=$('footerHelp').onclick=()=>openDialog('helpDialog');$('collectionTab').onclick=$('allPetsBtn').onclick=$('endCollectionBtn').onclick=()=>openCollection();$('playTab').onclick=()=>canvas.focus({preventScroll:true});$('pauseBtn').onclick=pause;$('resumeBtn').onclick=resume;$('retryBtn').onclick=newGame;$('restartBtn').onclick=$('restartPauseBtn').onclick=()=>openDialog('restartDialog');$('confirmRestart').onclick=()=>{resumeAfterDialog=false;$('restartDialog').close();newGame();};
for(const name of['swap','remove','shake'])$(name+'Btn').onclick=()=>game.useTool(name);
function refreshSound(){$('soundBtn').classList.toggle('sound-on',saved.sound);$('soundBtn').ariaLabel=saved.sound?'关闭声音':'开启声音';$('soundBtn').title=$('soundBtn').ariaLabel;}
$('soundBtn').onclick=()=>{saved.sound=!saved.sound;save();refreshSound();if(saved.sound)sound('tool');};
function position(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*WIDTH,y:(e.clientY-r.top)/r.height*HEIGHT};}
canvas.addEventListener('pointermove',e=>{if(e.isPrimary&&game.state==='playing'&&!game.removing)game.setAim(position(e).x);});
canvas.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0||game.state!=='playing')return;e.preventDefault();heldPointer=e.pointerId;canvas.setPointerCapture(e.pointerId);const p=position(e);if(!game.removing)game.setAim(p.x);});
canvas.addEventListener('pointerup',e=>{if(heldPointer!==e.pointerId)return;heldPointer=null;const p=position(e);if(game.removing)game.pickRemove(p.x,p.y);else game.drop();});
canvas.addEventListener('pointercancel',()=>{heldPointer=null;});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(['ArrowLeft','ArrowRight',' '].includes(e.key)&&!e.target.closest('button')){e.preventDefault();if(e.key===' ')game.drop();else game.setAim(game.aim+(e.key==='ArrowLeft'?-1:1)*20);}if(e.key==='p'||e.key==='P')game.state==='paused'?resume():pause();if(e.key==='Escape'){if(game.removing)game.useTool('remove');else if(game.state==='paused')resume();else pause();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
// Soft graph paper, a little machinery, and a basket that belongs in the forest.
function line(x1,y1,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();}
function rounded(x,y,w,h,r,fill,stroke,lw=1){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=lw;ctx.strokeStyle=stroke;ctx.stroke();}}
function drawBasket(){
 ctx.fillStyle='#e5ebd3';ctx.beginPath();ctx.ellipse(230,533,196,18,0,0,Math.PI*2);ctx.fill();
 for(const flip of[false,true]){ctx.save();if(flip){ctx.translate(460,0);ctx.scale(-1,1);}ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(25,310);ctx.lineTo(42,307);ctx.lineTo(76,525);ctx.lineTo(60,529);ctx.closePath();ctx.fillStyle='#b1c098';ctx.fill();ctx.strokeStyle='#627955';ctx.lineWidth=2;ctx.stroke();line(31,315,65,521,'#f5f5d9',3);for(let y=326;y<520;y+=14){const x=27+(y-310)*.16;line(x,y,x+12,y-2,'#71895e',1);}for(const y of[317,511]){const x=32+(y-310)*.16;ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fillStyle='#edf2d7';ctx.fill();}ctx.restore();}
 rounded(60,524,340,13,4,'#a9ba8e','#627955',2);line(70,528,389,528,'#dae4bf',2);for(let x=80;x<393;x+=21)line(x,532,x+8,532,'#849967',1);
 // Little plants outside the basket.
 for(const side of[-1,1]){ctx.save();ctx.translate(side===-1?25:435,524);ctx.scale(side,1);line(0,0,3,-31,'#a0b187',1.5);for(const yy of[-9,-21]){ctx.fillStyle='#c4d0ad';ctx.beginPath();ctx.ellipse(-2,yy,5,9,-.5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(7,yy-5,4,8,.6,0,Math.PI*2);ctx.fill();}ctx.restore();}
}
function drawClaw(t){drawX+=(game.aim-drawX)*.23;const open=t-dropAt<.28,release=Math.max(0,1-(t-dropAt)/.45);ctx.save();ctx.translate(drawX,0);line(0,0,0,58,'#697c5b',2);line(-4,0,-4,55,'#c2cdb0',1);rounded(-12,49,24,18,5,'#d4dfc0','#697c5b',1.6);rounded(-18,66,36,11,5,'#a9bf90','#617952',1.8);rounded(-7,51,14,12,3,'#eef3de');
 if(game.time>=game.readyAt-.1&&game.state!=='ended'&&game.state!=='won'){ctx.globalAlpha=game.time<game.readyAt?.35:1;drawPet(ctx,game.current,0,113,PETS[game.current].radius,0,t);ctx.globalAlpha=1;}
 for(const s of[-1,1]){const ext=open?12*release:0;ctx.beginPath();ctx.moveTo(s*14,75);ctx.lineTo(s*(28+ext),93);ctx.lineTo(s*(24+ext),117);ctx.lineTo(s*(18+ext),123);ctx.strokeStyle='#52694a';ctx.lineWidth=8;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();ctx.strokeStyle='#f0f3de';ctx.lineWidth=4;ctx.stroke();ctx.beginPath();ctx.arc(s*16,76,3,0,Math.PI*2);ctx.fillStyle='#94aa7b';ctx.fill();}
 // Aim guide ends at the first pet directly below the claw.
 if(game.state==='playing'&&!game.removing&&game.time>=game.readyAt){let end=516;for(const b of game.pets){const r=PETS[b.petLevel].radius,dx=b.position.x-drawX;if(Math.abs(dx)<r)end=Math.min(end,b.position.y-Math.sqrt(r*r-dx*dx));}ctx.setLineDash([2,7]);line(0,145,0,end-4,'#8c9f754a',1);ctx.setLineDash([]);ctx.beginPath();ctx.ellipse(0,end+3,9,2,0,0,Math.PI*2);ctx.fillStyle='#7e986c2e';ctx.fill();}ctx.restore();}
function drawFrame(now){const t=game.time;ctx.clearRect(0,0,WIDTH,HEIGHT);ctx.fillStyle='#f6f7ec';ctx.fillRect(0,0,WIDTH,HEIGHT);ctx.strokeStyle='#d9e1cb66';ctx.lineWidth=.6;ctx.beginPath();for(let x=0;x<WIDTH;x+=23){ctx.moveTo(x,0);ctx.lineTo(x,HEIGHT);}for(let y=6;y<HEIGHT;y+=23){ctx.moveTo(0,y);ctx.lineTo(WIDTH,y);}ctx.stroke();const bg=ctx.createLinearGradient(0,350,0,560);bg.addColorStop(0,'#dbe6c000');bg.addColorStop(1,'#dce6c270');ctx.fillStyle=bg;ctx.fillRect(0,300,WIDTH,260);
 ctx.save();if(t<shakeUntil&&!reducedMotion)ctx.translate(Math.sin(t*70)*3,0);
 // The limit stays visible, and turns coral as the basket fills.
 ctx.setLineDash([4,6]);line(26,DANGER_Y,434,DANGER_Y,game.danger>0?'#ce9078':'#b8c5a17a',1);ctx.setLineDash([]);ctx.fillStyle=game.danger>0?'#bd7a62':'#aab598';ctx.font='8px "DM Sans",sans-serif';ctx.textAlign='left';ctx.fillText('留一点呼吸空间',31,DANGER_Y-8);ctx.textAlign='right';ctx.fillText(game.danger>0?`${Math.max(0,3-game.danger).toFixed(1)} s`:'GROW SLOWLY',427,DANGER_Y-8);
 // Ground shadows are inexpensive and preserve crisp silhouettes.
 for(const b of game.pets){const r=PETS[b.petLevel].radius,above=528-b.position.y-r;if(above<160){ctx.fillStyle=`rgba(73,99,48,${Math.max(0,.09-above*.0005)})`;ctx.beginPath();ctx.ellipse(b.position.x,527,r*.72,Math.max(2,r*.1),0,0,Math.PI*2);ctx.fill();}}
 for(const b of game.pets){const age=t-b.visualBorn,pop=reducedMotion?1:Math.min(1,age*7);drawPet(ctx,b.petLevel,b.position.x,b.position.y,PETS[b.petLevel].radius*(.82+.18*pop),b.angle,t);}
 drawBasket();drawClaw(t);
 rounded(367,26,67,87,13,'#fbfcf3cc','#dce4cf');ctx.fillStyle='#97a88a';ctx.font='8px \"DM Sans\",sans-serif';ctx.textAlign='center';ctx.fillText('下一只',400,44);drawPet(ctx,game.next,400,80,21,0,t);
 for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
 for(const f of floaters){ctx.globalAlpha=Math.min(1,f.life*1.6);ctx.textAlign='center';ctx.font='600 20px Outfit,sans-serif';ctx.lineWidth=4;ctx.strokeStyle='#f6f7ec';ctx.strokeText(f.text,f.x,f.y);ctx.fillStyle='#78935c';ctx.fillText(f.text,f.x,f.y);}ctx.globalAlpha=1;
 if(game.removing){for(const b of game.pets){ctx.setLineDash([3,4]);ctx.strokeStyle='#c19162';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(b.position.x,b.position.y,PETS[b.petLevel].radius+5,0,Math.PI*2);ctx.stroke();}ctx.setLineDash([]);}
 ctx.restore();canvas.parentElement.classList.toggle('in-danger',game.danger>0);
}
function loop(now){const dt=Math.min(50,now-(last||now));last=now;if(game.state==='playing'){accumulator+=dt;while(accumulator>=1000/60){game.step();accumulator-=1000/60;}for(const p of particles){p.x+=p.vx*dt/16;p.y+=p.vy*dt/16;p.vy+=dt*.002;p.life-=dt*.0015;}particles=particles.filter(p=>p.life>0);for(const f of floaters){f.y-=dt*.025;f.life-=dt*.001;}floaters=floaters.filter(f=>f.life>0);}drawFrame(now);requestAnimationFrame(loop);}
const dpr=Math.min(devicePixelRatio||1,2);canvas.width=WIDTH*dpr;canvas.height=HEIGHT*dpr;ctx.scale(dpr,dpr);
const hero=fitCanvas($('heroPet'),260,200);drawPet(hero,3,171,131,33,.12,0,{shadow:true,still:true});drawPet(hero,0,106,101,49,-.12,0,{shadow:true,still:true});
for(const [id,level]of[['helpPetA',0],['helpPetB',0],['helpPetC',1]])petIcon($(id),level,100,100,false,30);
refreshCollection();refreshSound();newGame();requestAnimationFrame(loop);
})();
